suppressPackageStartupMessages(library(data.table));setDTthreads(2)
BASE='almanac_conditionals/state_conditioned_bridge/program_first';g=readRDS('almanac_conditionals/state_conditioned_bridge/sensitivity_selected/artifacts/eligible_gene_measurements.rds');m=fread(file.path(BASE,'results/full_tahoe_profile_metadata.tsv.gz'));genes=fread(file.path(BASE,'results/selected_gene_universe.tsv'))$gene
key=function(x)paste(x$depmap_id,x$drug,x$dose);ii=match(key(g$metadata),key(m));available=which(!is.na(ii)&g$metadata$source=='original cache');stopifnot(length(available)>0,!anyDuplicated(key(m)))
con=file(file.path(BASE,'artifacts/full_tahoe_candidate_responses.npy'),'rb');stopifnot(rawToChar(readBin(con,'raw',6))=='\x93NUMPY');v=readBin(con,'integer',2,size=1,signed=F);n=readBin(con,'integer',1,size=if(v[1]==1)2 else 4,signed=F,endian='little');h=rawToChar(readBin(con,'raw',n));dims=as.integer(strsplit(sub(".*'shape': \\(([^)]*)\\).*",'\\1',h),',')[[1]]);dims=dims[!is.na(dims)];stopifnot(!grepl('True',h),dims[2]==length(genes));size=if(grepl('f8',h))8 else 4;offset=seek(con);err=numeric(length(available))
for(j in seq_along(available)){i=available[j];seek(con,offset+size*dims[2]*(ii[i]-1),origin='start');x=readBin(con,'numeric',dims[2],size=size,endian='little');err[j]=max(abs(x-g$response[i,genes]))};close(con);stopifnot(max(err)<1e-6)
audit=data.table(depmap_id=g$metadata$depmap_id[available],drug=g$metadata$drug[available],dose=g$metadata$dose[available],genes=length(genes),max_absolute_difference=err);fwrite(audit,file.path(BASE,'results/tahoe_normalization_identity.tsv'),sep='\t');cat(length(available),'overlapping profiles;',length(genes),'genes; max error',max(err),'\n')
